/* From Uiverse.io by csozidev - Tags: minimalist, switch, click, click effect, interactive, minecraft */
/* Minecraft switch made by: csozi | Website: english.csozi.hu*/

/* The switch - the box around the slider */
.__UIV_SCOPE__ .switch {
  font-size: 17px;
  position: relative;
  display: inline-block;
  width: 4em;
  height: 2em;
}

/* Hide default HTML checkbox */
.__UIV_SCOPE__ .switch input {
  opacity: 1;
  width: 0;
  height: 0;
}

/* The slider */
.__UIV_SCOPE__ .slider {
  position: absolute;
  cursor: pointer;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: #ccc;
  transition: .4s;
}

.__UIV_SCOPE__ .off {
  position: absolute;
  content: "";
  height: 2em;
  width: 2em;
  background-color: white;
  transition: .4s;
  image-rendering: pixelated;
  opacity: 1;
}

.__UIV_SCOPE__ .on {
  position: absolute;
  content: "";
  height: 2em;
  width: 2em;
  background-color: white;
  transition: .4s;
  image-rendering: pixelated;
  opacity: 0;
}

.__UIV_SCOPE__ .switch input:checked + .slider {
  background-color: #ccc;
}

.__UIV_SCOPE__ .switch input:focus + .slider {
  box-shadow: 0 0 1px #ccc;
}

.__UIV_SCOPE__ .switch input:checked ~ .off {
  transform: translateX(2em);
}

.__UIV_SCOPE__ .switch input:checked ~ .on {
  transform: translateX(2em);
  opacity: 1;
}
